CREATE OR REPLACE FUNCTION public.attendance_delivery_roster(p_slot_id uuid) RETURNS uuid[]
LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT coalesce(array_agg(DISTINCT s.id ORDER BY s.id),ARRAY[]::uuid[])
 FROM public.current_timetable_entries e
 JOIN public.departments d ON d.id=e.department_id
 JOIN public.current_student_registrations r ON r.campus_id=coalesce(e.campus_id,d.campus_id)
  AND r.academic_year=e.academic_year AND r.semester=e.semester
 JOIN public.students s ON s.id=r.student_id AND s.campus_id=r.campus_id AND s.current_semester=r.semester
 WHERE e.id=p_slot_id AND e.course_id=ANY(ARRAY[r.slot_1_course_id,r.slot_2_course_id,r.slot_3_course_id,
  r.slot_4_course_id,r.slot_5_course_id,r.slot_6_course_id,r.slot_7_course_id,r.slot_8_course_id]);
$$;
CREATE OR REPLACE FUNCTION public.assert_attendance_actor(p_actor uuid,p_slot uuid) RETURNS void
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE e record; f record;
BEGIN
 SELECT te.*,coalesce(te.campus_id,d.campus_id) host INTO e FROM public.current_timetable_entries te
  JOIN public.departments d ON d.id=te.department_id WHERE te.id=p_slot;
 IF NOT FOUND THEN RAISE EXCEPTION 'Delivery not found' USING ERRCODE='P4030'; END IF;
 IF EXISTS(SELECT 1 FROM public.admins WHERE id=p_actor) THEN RETURN; END IF;
 SELECT * INTO f FROM public.faculty WHERE id=p_actor;
 IF f.role='hod' AND f.department_id=e.department_id AND f.campus_id=e.host THEN RETURN; END IF;
 IF f.role='teacher' AND EXISTS(SELECT 1 FROM public.current_teacher_course_assignments a
  WHERE a.teacher_id=p_actor AND a.course_id=e.course_id AND a.campus_id=e.host
   AND a.academic_year=e.academic_year AND a.semester=e.semester AND a.term_version=e.term_version) THEN RETURN; END IF;
 RAISE EXCEPTION 'Actor is no longer authorized for this delivery' USING ERRCODE='P4030';
END $$;
CREATE OR REPLACE FUNCTION public.atomic_submit_period_attendance(p_slot_id uuid, p_attendance_date date, p_user_id uuid, p_absent_student_ids uuid[], p_all_roster_ids uuid[], p_course_id uuid, p_expected_revision integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
    v_entry RECORD;
    v_host_campus_id UUID;
    v_existing_session RECORD;
    v_current_rev INTEGER := 0;
    v_new_rev INTEGER := 1;
    v_rev_token TEXT;
    v_now TIMESTAMPTZ := timezone('utc'::text, now());
    v_total_students INTEGER := cardinality(p_all_roster_ids);
    v_absent_count INTEGER := cardinality(p_absent_student_ids);
    v_present_count INTEGER;
    v_stu_id UUID;
    v_stu_status TEXT;
    v_lock_key BIGINT;
BEGIN
  PERFORM pg_advisory_xact_lock(76102622134917::bigint);
    IF p_expected_revision IS NULL OR p_expected_revision < 0 THEN
      RAISE EXCEPTION 'A nonnegative integer revision is required' USING ERRCODE='22023'; END IF;
    IF p_absent_student_ids IS NULL OR cardinality(p_absent_student_ids)>10000 OR
      EXISTS(SELECT 1 FROM unnest(p_absent_student_ids) x GROUP BY x HAVING count(*)>1) OR
      array_position(p_absent_student_ids,NULL) IS NOT NULL THEN
      RAISE EXCEPTION 'Invalid or duplicate absentee IDs' USING ERRCODE='22023'; END IF;
    PERFORM public.assert_attendance_actor(p_user_id,p_slot_id);
    IF ARRAY(SELECT DISTINCT unnest(coalesce(p_all_roster_ids,ARRAY[]::uuid[])) ORDER BY 1)
       IS DISTINCT FROM public.attendance_delivery_roster(p_slot_id) THEN
      RAISE EXCEPTION 'ATTENDANCE_CONFLICT: roster changed; reload before submitting' USING ERRCODE='P4090'; END IF;
    p_all_roster_ids:=public.attendance_delivery_roster(p_slot_id);
    IF cardinality(p_all_roster_ids)=0 OR NOT p_absent_student_ids <@ p_all_roster_ids THEN
      RAISE EXCEPTION 'Absentee is not in the authoritative enrolled roster' USING ERRCODE='22023'; END IF;
    v_total_students:=cardinality(p_all_roster_ids);
    v_absent_count:=cardinality(p_absent_student_ids);
    -- A. Transactional advisory lock on (slot_id, attendance_date)
    v_lock_key := ('x' || substr(md5(p_slot_id::text || '_' || p_attendance_date::text), 1, 15))::bit(64)::bigint;
    PERFORM pg_advisory_xact_lock(v_lock_key);

    -- B. Verify published timetable entry exists
    SELECT te.id, te.course_id, te.status, te.academic_year, te.semester, te.campus_id, d.campus_id AS dept_campus_id
    INTO v_entry
    FROM public.current_timetable_entries te
    LEFT JOIN departments d ON d.id = te.department_id
    WHERE te.id = p_slot_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Timetable entry % not found', p_slot_id;
    END IF;

    IF v_entry.status != 'published' THEN
        RAISE EXCEPTION 'Attendance requires a published schedule (status: %) (F43)', v_entry.status;
    END IF;

    IF v_entry.course_id IS DISTINCT FROM p_course_id THEN RAISE EXCEPTION 'Course does not match delivery'; END IF;
    v_host_campus_id := COALESCE(v_entry.campus_id, v_entry.dept_campus_id);

    -- C. R28: Verify cohort is active (not retired)
    IF NOT EXISTS (SELECT 1 FROM public.campus_settings WHERE campus_id = v_host_campus_id) THEN RAISE EXCEPTION 'Campus term unavailable'; END IF;

    PERFORM public.assert_attendance_term(p_slot_id,p_attendance_date);
    -- D. R29: Query existing dated-session with FOR UPDATE
    SELECT * INTO v_existing_session
    FROM period_attendance_sessions
    WHERE timetable_slot_id = p_slot_id
      AND attendance_date = p_attendance_date
    FOR UPDATE;

    IF FOUND THEN
        v_current_rev := v_existing_session.revision;
        -- If client provided an expected revision, strictly require match
        IF p_expected_revision IS NOT NULL AND p_expected_revision > 0 THEN
            IF p_expected_revision != v_current_rev THEN
                RAISE EXCEPTION 'ATTENDANCE_CONFLICT: Session revision mismatch. Current revision is %, expected % (R29)',
                    v_current_rev, p_expected_revision;
            END IF;
        ELSIF p_expected_revision = 0 THEN
            -- Client expected first submission, but session already exists
            RAISE EXCEPTION 'ATTENDANCE_CONFLICT: Session already marked at revision % (R29)', v_current_rev;
        END IF;

        v_new_rev := v_current_rev + 1;
    ELSE
        -- No session exists: if client expected an existing revision, conflict
        IF p_expected_revision IS NOT NULL AND p_expected_revision > 0 THEN
            RAISE EXCEPTION 'ATTENDANCE_CONFLICT: Expected revision % but session is unmarked (R29)', p_expected_revision;
        END IF;
        v_new_rev := 1;
    END IF;

    v_present_count := v_total_students - v_absent_count;
    v_rev_token := md5(p_slot_id::text || '_' || p_attendance_date::text || '_' || v_new_rev::text);

    -- E. Upsert student marks atomically
    FOREACH v_stu_id IN ARRAY p_all_roster_ids
    LOOP
        IF v_stu_id = ANY(p_absent_student_ids) THEN
            v_stu_status := 'absent';
        ELSE
            v_stu_status := 'present';
        END IF;

        INSERT INTO period_attendance (
            timetable_slot_id,
            student_id,
            course_id,
            marked_by,
            status,
            marked_at,
            attendance_date,
            is_late_entry
        )
        VALUES (
            p_slot_id,
            v_stu_id,
            p_course_id,
            p_user_id,
            v_stu_status,
            v_now,
            p_attendance_date,
            false
        )
        ON CONFLICT (timetable_slot_id, student_id, attendance_date)
        DO UPDATE SET
            status = EXCLUDED.status,
            marked_by = EXCLUDED.marked_by,
            marked_at = EXCLUDED.marked_at;
    END LOOP;

    IF EXISTS(SELECT 1 FROM public.period_attendance WHERE timetable_slot_id=p_slot_id AND attendance_date=p_attendance_date
      AND NOT student_id=ANY(p_all_roster_ids)) THEN
      RAISE EXCEPTION 'ATTENDANCE_CONFLICT: saved marks contain students outside the current roster; review required'; END IF;
    SELECT count(*),count(*) FILTER(WHERE status='absent'),count(*) FILTER(WHERE status='present')
      INTO v_total_students,v_absent_count,v_present_count FROM public.period_attendance
      WHERE timetable_slot_id=p_slot_id AND attendance_date=p_attendance_date;
    INSERT INTO public.system_logs(log_type,event_type,user_id,action,resource_type,resource_id,status,metadata)
      VALUES('audit_event','period_attendance_marked',p_user_id,'submitted dated attendance','period_attendance',p_slot_id,'success',
      jsonb_build_object('attendance_date',p_attendance_date,'revision',v_new_rev));
    -- F. Upsert session revision
    INSERT INTO period_attendance_sessions (
        timetable_slot_id,
        attendance_date,
        revision,
        revision_token,
        marked_by,
        last_marked_at,
        total_students,
        present_count,
        absent_count,
        updated_at
    )
    VALUES (
        p_slot_id,
        p_attendance_date,
        v_new_rev,
        v_rev_token,
        p_user_id,
        v_now,
        v_total_students,
        v_present_count,
        v_absent_count,
        v_now
    )
    ON CONFLICT (timetable_slot_id, attendance_date)
    DO UPDATE SET
        revision = v_new_rev,
        revision_token = v_rev_token,
        marked_by = EXCLUDED.marked_by,
        last_marked_at = EXCLUDED.last_marked_at,
        total_students = EXCLUDED.total_students,
        present_count = EXCLUDED.present_count,
        absent_count = EXCLUDED.absent_count,
        updated_at = v_now;

    RETURN jsonb_build_object(
        'success', true,
        'revision', v_new_rev,
        'revision_token', v_rev_token,
        'attendance_date', p_attendance_date,
        'marked_at', v_now,
        'total_students', v_total_students,
        'present_count', v_present_count,
        'absent_count', v_absent_count
    );
END;
$function$;
CREATE OR REPLACE FUNCTION public.atomic_copy_practical_attendance(p_source_slot_id uuid, p_target_slot_id uuid, p_attendance_date date, p_user_id uuid, p_expected_target_revision integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
    v_src RECORD;
    v_tgt RECORD;
    v_src_campus_id UUID;
    v_tgt_campus_id UUID;
    v_src_period INTEGER;
    v_tgt_period INTEGER;
    v_tgt_session RECORD;
    v_current_tgt_rev INTEGER := 0;
    v_new_tgt_rev INTEGER := 1;
    v_tgt_rev_token TEXT;
    v_now TIMESTAMPTZ := timezone('utc'::text, now());
    v_copied_count INTEGER := 0;
    v_present_count INTEGER := 0;
    v_absent_count INTEGER := 0;
    v_lock_key BIGINT;
    v_mark RECORD;
BEGIN
  PERFORM pg_advisory_xact_lock(76102622134917::bigint);
    IF p_expected_target_revision IS NULL OR p_expected_target_revision < 0 THEN
      RAISE EXCEPTION 'A nonnegative integer target revision is required' USING ERRCODE='22023'; END IF;
    PERFORM public.assert_attendance_actor(p_user_id,p_source_slot_id);
    PERFORM public.assert_attendance_actor(p_user_id,p_target_slot_id);
    IF public.attendance_delivery_roster(p_source_slot_id) IS DISTINCT FROM public.attendance_delivery_roster(p_target_slot_id)
      OR public.attendance_delivery_roster(p_source_slot_id) IS DISTINCT FROM
        ARRAY(SELECT student_id FROM public.period_attendance WHERE timetable_slot_id=p_source_slot_id
          AND attendance_date=p_attendance_date ORDER BY student_id) THEN
      RAISE EXCEPTION 'ATTENDANCE_CONFLICT: source marks do not cover the complete current roster'; END IF;
    -- A. Transactional advisory lock on target session
    v_lock_key := ('x' || substr(md5(p_target_slot_id::text || '_' || p_attendance_date::text), 1, 15))::bit(64)::bigint;
    PERFORM pg_advisory_xact_lock(v_lock_key);

    -- B. Query source timetable entry
    SELECT
        te.id, te.course_id, te.department_id, te.campus_id, te.academic_year,
        te.semester, te.status, te.session_type, te.is_lab_block,
        ts.day_of_week, ts.period_number,
        d.campus_id AS dept_campus_id
    INTO v_src
    FROM public.current_timetable_entries te
    JOIN time_slots ts ON ts.id = te.time_slot_id
    LEFT JOIN departments d ON d.id = te.department_id
    WHERE te.id = p_source_slot_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Source timetable entry % not found', p_source_slot_id;
    END IF;

    -- C. Query target timetable entry
    SELECT
        te.id, te.course_id, te.department_id, te.campus_id, te.academic_year,
        te.semester, te.status, te.session_type, te.is_lab_block,
        ts.day_of_week, ts.period_number,
        d.campus_id AS dept_campus_id
    INTO v_tgt
    FROM public.current_timetable_entries te
    JOIN time_slots ts ON ts.id = te.time_slot_id
    LEFT JOIN departments d ON d.id = te.department_id
    WHERE te.id = p_target_slot_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Target timetable entry % not found', p_target_slot_id;
    END IF;

    -- D. R03: Validate publication status
    IF v_src.status != 'published' OR v_tgt.status != 'published' THEN
        RAISE EXCEPTION 'Both practical periods must be published (R03/F43)';
    END IF;

    -- E. R03: Validate matching course and cohort identity
    IF v_src.course_id != v_tgt.course_id THEN
        RAISE EXCEPTION 'Cannot copy practical attendance between different courses (R03)';
    END IF;

    IF v_src.department_id != v_tgt.department_id THEN
        RAISE EXCEPTION 'Cannot copy practical attendance between different departments (R03)';
    END IF;

    v_src_campus_id := COALESCE(v_src.campus_id, v_src.dept_campus_id);
    v_tgt_campus_id := COALESCE(v_tgt.campus_id, v_tgt.dept_campus_id);

    IF v_src_campus_id != v_tgt_campus_id THEN
        RAISE EXCEPTION 'Cannot copy practical attendance between different campuses (R03)';
    END IF;

    IF v_src.academic_year != v_tgt.academic_year OR v_src.semester != v_tgt.semester THEN
        RAISE EXCEPTION 'Cannot copy practical attendance between different academic years or semesters (R03)';
    END IF;

    -- F. R28: Verify cohort is not retired
    IF NOT EXISTS (SELECT 1 FROM public.campus_settings WHERE campus_id = v_src_campus_id) THEN RAISE EXCEPTION 'Campus term unavailable'; END IF;

    -- G. R03: Validate both are practical sessions
    IF NOT (v_src.is_lab_block = true OR v_src.session_type = 'practical') OR
       NOT (v_tgt.is_lab_block = true OR v_tgt.session_type = 'practical') THEN
        RAISE EXCEPTION 'Practical attendance copying is only allowed between practical / lab sessions (R03)';
    END IF;

    -- H. R03: Validate matching day of week and consecutive practical pair
    IF v_src.day_of_week != v_tgt.day_of_week THEN
        RAISE EXCEPTION 'Cannot copy practical attendance between different days of the week (R03)';
    END IF;

    PERFORM public.assert_attendance_term(p_source_slot_id,p_attendance_date);
    PERFORM public.assert_attendance_term(p_target_slot_id,p_attendance_date);
    v_src_period := v_src.period_number;
    v_tgt_period := v_tgt.period_number;

    -- Strictly forbid lunch-crossing pair (Period 3 to Period 4)
    IF v_src_period = 3 AND v_tgt_period = 4 THEN
        RAISE EXCEPTION 'Cannot copy practical attendance across lunch boundary (Period 3 to Period 4 is forbidden) (R03)';
    END IF;

    -- Validate adjacent consecutive lab pair in domain: (1, 2), (2, 3), (4, 5), (5, 6)
    IF NOT (
        (v_src_period = 1 AND v_tgt_period = 2) OR
        (v_src_period = 2 AND v_tgt_period = 3) OR
        (v_src_period = 4 AND v_tgt_period = 5) OR
        (v_src_period = 5 AND v_tgt_period = 6)
    ) THEN
        RAISE EXCEPTION 'Invalid practical period pair (Period % to %). Practical copying requires an adjacent consecutive lab pair (R03)',
            v_src_period, v_tgt_period;
    END IF;

    -- I. Fetch source marks
    IF NOT EXISTS (
        SELECT 1 FROM period_attendance
        WHERE timetable_slot_id = p_source_slot_id
          AND attendance_date = p_attendance_date
    ) THEN
        RAISE EXCEPTION 'Source practical period has no attendance recorded for % (R03)', p_attendance_date;
    END IF;

    -- J. R29: Query target session revision
    SELECT * INTO v_tgt_session
    FROM period_attendance_sessions
    WHERE timetable_slot_id = p_target_slot_id
      AND attendance_date = p_attendance_date
    FOR UPDATE;

    IF FOUND THEN
        v_current_tgt_rev := v_tgt_session.revision;
        IF p_expected_target_revision IS NOT NULL AND p_expected_target_revision > 0 THEN
            IF p_expected_target_revision != v_current_tgt_rev THEN
                RAISE EXCEPTION 'ATTENDANCE_CONFLICT: Target session revision mismatch. Current revision is %, expected % (R29)',
                    v_current_tgt_rev, p_expected_target_revision;
            END IF;
        ELSIF p_expected_target_revision = 0 THEN
            RAISE EXCEPTION 'ATTENDANCE_CONFLICT: Target period already marked at revision %. Provide expected revision to overwrite (R29)',
                v_current_tgt_rev;
        END IF;

        v_new_tgt_rev := v_current_tgt_rev + 1;
    ELSE
        IF p_expected_target_revision IS NOT NULL AND p_expected_target_revision > 0 THEN
            RAISE EXCEPTION 'ATTENDANCE_CONFLICT: Expected target revision % but target session is unmarked (R29)',
                p_expected_target_revision;
        END IF;
        v_new_tgt_rev := 1;
    END IF;

    v_tgt_rev_token := md5(p_target_slot_id::text || '_' || p_attendance_date::text || '_' || v_new_tgt_rev::text);

    -- K. Atomically duplicate marks into target period
    FOR v_mark IN (
        SELECT student_id, course_id, status
        FROM period_attendance
        WHERE timetable_slot_id = p_source_slot_id
          AND attendance_date = p_attendance_date
    ) LOOP
        INSERT INTO period_attendance (
            timetable_slot_id,
            student_id,
            course_id,
            marked_by,
            status,
            marked_at,
            attendance_date,
            is_late_entry
        )
        VALUES (
            p_target_slot_id,
            v_mark.student_id,
            v_mark.course_id,
            p_user_id,
            v_mark.status,
            v_now,
            p_attendance_date,
            false
        )
        ON CONFLICT (timetable_slot_id, student_id, attendance_date)
        DO UPDATE SET
            status = EXCLUDED.status,
            marked_by = EXCLUDED.marked_by,
            marked_at = EXCLUDED.marked_at;

        v_copied_count := v_copied_count + 1;
        IF v_mark.status = 'present' THEN
            v_present_count := v_present_count + 1;
        ELSE
            v_absent_count := v_absent_count + 1;
        END IF;
    END LOOP;

    IF EXISTS(SELECT 1 FROM public.period_attendance WHERE timetable_slot_id=p_target_slot_id AND attendance_date=p_attendance_date
      AND NOT student_id=ANY(public.attendance_delivery_roster(p_target_slot_id))) THEN
      RAISE EXCEPTION 'ATTENDANCE_CONFLICT: saved target roster changed; review required'; END IF;
    INSERT INTO public.system_logs(log_type,event_type,user_id,action,resource_type,resource_id,status,metadata)
      VALUES('audit_event','period_attendance_copied',p_user_id,'copied dated practical attendance','period_attendance',p_target_slot_id,'success',
      jsonb_build_object('source_slot_id',p_source_slot_id,'attendance_date',p_attendance_date,'revision',v_new_tgt_rev));
    -- L. Upsert target session revision
    INSERT INTO period_attendance_sessions (
        timetable_slot_id,
        attendance_date,
        revision,
        revision_token,
        marked_by,
        last_marked_at,
        total_students,
        present_count,
        absent_count,
        updated_at
    )
    VALUES (
        p_target_slot_id,
        p_attendance_date,
        v_new_tgt_rev,
        v_tgt_rev_token,
        p_user_id,
        v_now,
        v_copied_count,
        v_present_count,
        v_absent_count,
        v_now
    )
    ON CONFLICT (timetable_slot_id, attendance_date)
    DO UPDATE SET
        revision = v_new_tgt_rev,
        revision_token = v_tgt_rev_token,
        marked_by = EXCLUDED.marked_by,
        last_marked_at = EXCLUDED.last_marked_at,
        total_students = EXCLUDED.total_students,
        present_count = EXCLUDED.present_count,
        absent_count = EXCLUDED.absent_count,
        updated_at = v_now;

    RETURN jsonb_build_object(
        'success', true,
        'copied_count', v_copied_count,
        'present_count', v_present_count,
        'absent_count', v_absent_count,
        'target_revision', v_new_tgt_rev,
        'target_revision_token', v_tgt_rev_token,
        'attendance_date', p_attendance_date,
        'marked_at', v_now
    );
END;
$function$;

-- NOT VALID preserves existing records for owner review, while protecting every new/updated summary.
ALTER TABLE public.period_attendance_sessions ADD CONSTRAINT review_attendance_totals
 CHECK(total_students>=0 AND present_count>=0 AND absent_count>=0 AND present_count+absent_count=total_students) NOT VALID;
ALTER TABLE public.campus_settings ADD CONSTRAINT review_credit_range CHECK(min_credits>=0 AND max_credits>=min_credits) NOT VALID;
ALTER TABLE public.faculty ADD CONSTRAINT review_teacher_department CHECK(role<>'teacher' OR department_id IS NOT NULL) NOT VALID;
DO $$ DECLARE f regprocedure; BEGIN
 FOREACH f IN ARRAY ARRAY['public.attendance_delivery_roster(uuid)'::regprocedure,'public.assert_attendance_actor(uuid,uuid)'::regprocedure,
 'public.atomic_submit_period_attendance(uuid,date,uuid,uuid[],uuid[],uuid,integer)'::regprocedure,
 'public.atomic_copy_practical_attendance(uuid,uuid,date,uuid,integer)'::regprocedure] LOOP
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',f);
 EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',f);
 END LOOP;
END $$;
NOTIFY pgrst,'reload schema';



-- Source: review_operations.sql
-- Owner-run after review_integrity.sql. No existing accounts or academic records are repaired.

SET LOCAL lock_timeout='10s';
CREATE TABLE public.review_jobs (
 id uuid PRIMARY KEY, kind text NOT NULL CHECK(kind IN('allocation','timetable')),
 campus_id uuid NOT NULL, actor_id uuid NOT NULL, academic_year text NOT NULL, semester integer NOT NULL,
 term_version integer NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'queued'
 CHECK(status IN('queued','running','completed','failed','cancelled')),
 fence uuid NOT NULL DEFAULT gen_random_uuid(), attempts integer NOT NULL DEFAULT 0,
 lease_until timestamptz, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), updated_at timestamptz NOT NULL DEFAULT clock_timestamp(), error text
);
CREATE UNIQUE INDEX review_jobs_active_cohort ON public.review_jobs(kind,campus_id,academic_year,semester,term_version) WHERE status IN('queued','running');
CREATE INDEX review_jobs_ready ON public.review_jobs(status,created_at);
ALTER TABLE public.review_jobs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.review_jobs FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.review_jobs TO service_role;

CREATE TABLE public.review_worker_state (id boolean PRIMARY KEY DEFAULT true CHECK(id),last_seen timestamptz NOT NULL DEFAULT clock_timestamp());
ALTER TABLE public.review_worker_state ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.review_worker_state FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE ON public.review_worker_state TO service_role;
CREATE FUNCTION public.guard_review_worker_completion() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
 IF NEW.status='completed' AND OLD.status IS DISTINCT FROM 'completed'
 AND EXISTS(SELECT 1 FROM public.review_jobs WHERE id=NEW.id)
 AND NOT EXISTS(SELECT 1 FROM public.review_jobs q JOIN public.faculty f ON f.id=q.actor_id AND f.role='campus_director' AND f.campus_id=q.campus_id
 JOIN public.campus_settings c ON c.campus_id=q.campus_id AND c.term_version=q.term_version
 WHERE q.id=NEW.id AND q.status='running' AND q.lease_until>clock_timestamp() AND q.fence::text=NEW.metadata->>'fencing_token') THEN
 RAISE EXCEPTION 'Worker authority, term or lease changed before completion' USING ERRCODE='P4030'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER review_worker_completion BEFORE UPDATE ON public.system_logs FOR EACH ROW EXECUTE FUNCTION public.guard_review_worker_completion();

CREATE FUNCTION public.enqueue_review_job(p_kind text,p_campus uuid,p_actor uuid,p_term integer,p_year text,p_semester integer,p_payload jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE job uuid; claim jsonb; token uuid:=gen_random_uuid();
BEGIN
 PERFORM pg_advisory_xact_lock(76102622134917::bigint);
 IF NOT EXISTS(SELECT 1 FROM public.faculty WHERE id=p_actor AND role='campus_director' AND campus_id=p_campus) THEN
 RAISE EXCEPTION 'Campus director required' USING ERRCODE='P4030'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.campus_settings WHERE campus_id=p_campus AND term_version=p_term AND academic_year=p_year) THEN
 RAISE EXCEPTION 'Campus term changed; reload' USING ERRCODE='P4090'; END IF;
 IF p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' OR octet_length(p_payload::text)>2097152 THEN RAISE EXCEPTION 'Invalid job payload'; END IF;
 SELECT id INTO job FROM public.review_jobs WHERE kind=p_kind AND campus_id=p_campus AND academic_year=p_year AND semester=p_semester
 AND term_version=p_term AND status IN('queued','running');
 IF FOUND THEN RETURN jsonb_build_object('runId',job,'jobId',job,'status','queued'); END IF;
 IF p_kind='allocation' THEN
  job:=public.claim_allocation_run(p_campus,p_year,p_semester::smallint,p_actor,600,token);
 ELSIF p_kind='timetable' THEN
  claim:=public.claim_timetable_generation_job(p_campus,p_year,p_semester::smallint,p_actor,600,token); job:=(claim->>'job_id')::uuid;
 ELSE RAISE EXCEPTION 'Unsupported job kind'; END IF;
 INSERT INTO public.review_jobs(id,kind,campus_id,actor_id,academic_year,semester,term_version,payload,fence)
 VALUES(job,p_kind,p_campus,p_actor,p_year,p_semester,p_term,p_payload,token);
 UPDATE public.system_logs SET status='queued',updated_at=clock_timestamp() WHERE id=job;
 RETURN jsonb_build_object('runId',job,'jobId',job,'status','queued','success',true);
END $$;

CREATE FUNCTION public.claim_review_job() RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE j public.review_jobs; token uuid:=gen_random_uuid();
BEGIN
 -- One shared expensive-job slot across every worker/API instance.
 PERFORM pg_advisory_xact_lock(76102622134917::bigint);
 PERFORM pg_advisory_xact_lock(76102622134918::bigint);
 INSERT INTO public.review_worker_state VALUES(true,clock_timestamp()) ON CONFLICT(id) DO UPDATE SET last_seen=clock_timestamp();
 IF EXISTS(SELECT 1 FROM public.review_jobs WHERE status='running' AND lease_until>clock_timestamp()) THEN RETURN NULL; END IF;
 UPDATE public.review_jobs q SET status='completed',updated_at=clock_timestamp() FROM public.system_logs l
 WHERE q.id=l.id AND q.status IN('queued','running') AND l.status='completed';
 UPDATE public.review_jobs SET status='failed',error='Worker retry limit reached',updated_at=clock_timestamp()
 WHERE status='running' AND lease_until<=clock_timestamp() AND attempts>=3;
 UPDATE public.system_logs l SET status='failed',error_message=q.error,updated_at=clock_timestamp(),completed_at=clock_timestamp()
 FROM public.review_jobs q WHERE q.id=l.id AND q.status='failed' AND l.status IN('queued','running');
 SELECT * INTO j FROM public.review_jobs WHERE status='queued' OR (status='running' AND lease_until<=clock_timestamp())
 ORDER BY created_at,id LIMIT 1 FOR UPDATE SKIP LOCKED;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.campus_settings WHERE campus_id=j.campus_id AND term_version=j.term_version AND academic_year=j.academic_year)
 OR NOT EXISTS(SELECT 1 FROM public.faculty WHERE id=j.actor_id AND role='campus_director' AND campus_id=j.campus_id) THEN
  UPDATE public.review_jobs SET status='failed',error='Authority or term changed',updated_at=clock_timestamp() WHERE id=j.id;
  UPDATE public.system_logs SET status='failed',error_message='Authority or term changed',completed_at=clock_timestamp(),updated_at=clock_timestamp() WHERE id=j.id;
  RETURN NULL;
 END IF;
 UPDATE public.review_jobs SET status='running',fence=token,attempts=attempts+1,lease_until=clock_timestamp()+interval '90 seconds',updated_at=clock_timestamp()
 WHERE id=j.id RETURNING * INTO j;
 UPDATE public.system_logs SET status='running',started_at=clock_timestamp(),updated_at=clock_timestamp(),completed_at=NULL,error_message=NULL,
 metadata=metadata||jsonb_build_object('fencing_token',token,'lease_seconds',600) WHERE id=j.id;
 RETURN to_jsonb(j);
END $$;

CREATE FUNCTION public.renew_review_job(p_id uuid,p_fence uuid) RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
 PERFORM pg_advisory_xact_lock(76102622134917::bigint);
 INSERT INTO public.review_worker_state VALUES(true,clock_timestamp()) ON CONFLICT(id) DO UPDATE SET last_seen=clock_timestamp();
 UPDATE public.review_jobs q SET lease_until=clock_timestamp()+interval '90 seconds',updated_at=clock_timestamp()
 WHERE q.id=p_id AND q.fence=p_fence AND q.status='running' AND q.lease_until>clock_timestamp()
 AND EXISTS(SELECT 1 FROM public.campus_settings s WHERE s.campus_id=q.campus_id AND s.term_version=q.term_version)
 AND EXISTS(SELECT 1 FROM public.faculty f WHERE f.id=q.actor_id AND f.role='campus_director' AND f.campus_id=q.campus_id);
 IF NOT FOUND THEN RETURN false; END IF;
 UPDATE public.system_logs SET started_at=clock_timestamp(),updated_at=clock_timestamp() WHERE id=p_id AND metadata->>'fencing_token'=p_fence::text AND status='running';
 RETURN true;
END $$;
CREATE FUNCTION public.finish_review_job(p_id uuid,p_fence uuid,p_error text DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE complete boolean;
BEGIN
 PERFORM pg_advisory_xact_lock(76102622134917::bigint);
 SELECT status='completed' INTO complete FROM public.system_logs WHERE id=p_id;
 UPDATE public.review_jobs SET status=CASE WHEN complete AND p_error IS NULL THEN 'completed' ELSE 'failed' END,
 error=left(p_error,2000),lease_until=NULL,updated_at=clock_timestamp() WHERE id=p_id AND fence=p_fence AND status='running' AND lease_until>clock_timestamp();
 IF NOT FOUND THEN RETURN false; END IF;
 IF NOT coalesce(complete,false) THEN UPDATE public.system_logs SET status='failed',completed_at=clock_timestamp(),updated_at=clock_timestamp(),
 error_message=coalesce(left(p_error,2000),error_message,'Worker did not complete') WHERE id=p_id AND metadata->>'fencing_token'=p_fence::text; END IF;
 RETURN true;
END $$;
CREATE FUNCTION public.cancel_review_job(p_id uuid,p_actor uuid) RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
 PERFORM pg_advisory_xact_lock(76102622134917::bigint);
 UPDATE public.review_jobs q SET status='cancelled',fence=gen_random_uuid(),lease_until=NULL,updated_at=clock_timestamp()
 WHERE id=p_id AND status IN('queued','running') AND EXISTS(SELECT 1 FROM public.faculty f WHERE f.id=p_actor AND role='campus_director' AND f.campus_id=q.campus_id);
 IF NOT FOUND THEN RAISE EXCEPTION 'Active job unavailable in your campus' USING ERRCODE='P4030'; END IF;
 UPDATE public.system_logs SET status='failed',error_message='Cancelled by director',completed_at=clock_timestamp(),updated_at=clock_timestamp(),
 metadata=metadata||jsonb_build_object('fencing_token',gen_random_uuid()) WHERE id=p_id;
 RETURN true;
END $$;

CREATE TABLE public.auth_cleanup_tasks (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL, user_id uuid NOT NULL,
 actor_id uuid NOT NULL, scope text NOT NULL, resource_id uuid NOT NULL,
 status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','running','completed','failed')),
 attempts integer NOT NULL DEFAULT 0, next_attempt timestamptz NOT NULL DEFAULT clock_timestamp(), lease_until timestamptz,
 fence uuid, error text, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), updated_at timestamptz NOT NULL DEFAULT clock_timestamp(), UNIQUE(request_id,user_id)
);
CREATE INDEX auth_cleanup_ready ON public.auth_cleanup_tasks(status,next_attempt);
ALTER TABLE public.auth_cleanup_tasks ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.auth_cleanup_tasks FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.auth_cleanup_tasks TO service_role;
CREATE FUNCTION public.review_delete_accounts(p_scope text,p_id uuid,p_actor uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE request uuid:=gen_random_uuid(); users uuid[]; depts uuid[]; course_ids uuid[]; student_ids uuid[]; result jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock(76102622134917::bigint);
 IF NOT EXISTS(SELECT 1 FROM public.admins WHERE id=p_actor) THEN RAISE EXCEPTION 'Superadmin required' USING ERRCODE='P4030'; END IF;
 IF p_scope='campus' THEN
  SELECT array_agg(id) INTO users FROM (SELECT id FROM public.students WHERE campus_id=p_id UNION SELECT id FROM public.faculty WHERE campus_id=p_id) u;
 ELSIF p_scope='department' THEN
  SELECT array_agg(id) INTO users FROM (SELECT id FROM public.students WHERE department_id=p_id UNION SELECT id FROM public.faculty WHERE department_id=p_id) u;
 ELSIF p_scope='faculty' THEN
  IF NOT EXISTS(SELECT 1 FROM public.faculty WHERE id=p_id AND role<>'teacher') THEN RAISE EXCEPTION 'Teachers remain HOD-managed'; END IF;
  users:=ARRAY[p_id];
 ELSE RAISE EXCEPTION 'Invalid cleanup scope'; END IF;
 INSERT INTO public.auth_cleanup_tasks(request_id,user_id,actor_id,scope,resource_id) SELECT request,id,p_actor,p_scope,p_id FROM unnest(users) id;
 IF p_scope IN('campus','department') THEN
  SELECT coalesce(array_agg(id),ARRAY[]::uuid[]) INTO depts FROM public.departments WHERE CASE WHEN p_scope='campus' THEN campus_id=p_id ELSE id=p_id END;
  SELECT coalesce(array_agg(id),ARRAY[]::uuid[]) INTO course_ids FROM public.courses WHERE department_id=ANY(depts);
  SELECT coalesce(array_agg(id),ARRAY[]::uuid[]) INTO student_ids FROM public.students WHERE id=ANY(users);
  IF EXISTS(SELECT 1 FROM public.review_jobs WHERE status IN('queued','running') AND (campus_id=p_id OR actor_id=ANY(users))) THEN
    RAISE EXCEPTION 'Cancel active campus work before deletion'; END IF;
  IF EXISTS(SELECT 1 FROM public.student_registrations r WHERE NOT r.student_id=ANY(student_ids)
    AND ARRAY[r.slot_1_course_id,r.slot_2_course_id,r.slot_3_course_id,r.slot_4_course_id,r.slot_5_course_id,r.slot_6_course_id,r.slot_7_course_id,r.slot_8_course_id] && course_ids)
   OR EXISTS(SELECT 1 FROM public.timetable_entries WHERE (course_id=ANY(course_ids) OR teacher_id=ANY(users))
     AND CASE WHEN p_scope='campus' THEN campus_id IS DISTINCT FROM p_id ELSE NOT department_id=ANY(depts) END)
   OR EXISTS(SELECT 1 FROM public.teacher_course_assignments WHERE (course_id=ANY(course_ids) OR teacher_id=ANY(users))
     AND campus_id IS DISTINCT FROM CASE WHEN p_scope='campus' THEN p_id ELSE (SELECT campus_id FROM public.departments WHERE id=p_id) END)
  THEN RAISE EXCEPTION 'Shared courses or visiting teachers are still required outside the deletion scope'; END IF;
  DELETE FROM public.timetable_entries WHERE department_id=ANY(depts) OR (p_scope='campus' AND campus_id=p_id);
  DELETE FROM public.teacher_course_assignments WHERE course_id=ANY(course_ids) OR teacher_id=ANY(users) OR (p_scope='campus' AND campus_id=p_id);
  DELETE FROM public.students WHERE id=ANY(student_ids);
  DELETE FROM public.timetable_conflicts WHERE course_id=ANY(course_ids) OR blocking_course_id=ANY(course_ids);
  DELETE FROM public.semester_blueprints WHERE department_id=ANY(depts);
  DELETE FROM public.courses WHERE id=ANY(course_ids);
  DELETE FROM public.faculty WHERE id=ANY(users);
  DELETE FROM public.departments WHERE id=ANY(depts);
  IF p_scope='campus' THEN
   DELETE FROM public.campus_settings WHERE campus_id=p_id;
   DELETE FROM public.campuses WHERE id=p_id;
  END IF;
 ELSE DELETE FROM public.faculty WHERE id=p_id; END IF;
 INSERT INTO public.system_logs(log_type,event_type,user_id,user_role,action,resource_type,resource_id,status,metadata)
 VALUES('audit_event','accounts_deleted',p_actor,'superadmin','deleted domain records; Auth cleanup queued',p_scope,p_id,'success',
 jsonb_build_object('request_id',request,'auth_accounts',coalesce(cardinality(users),0)));
 RETURN jsonb_build_object('success',true,'cleanupRequestId',request,'cleanupStatus',CASE WHEN cardinality(users)>0 THEN 'pending' ELSE 'completed' END,
 'pendingAuthAccounts',coalesce(cardinality(users),0));
END $$;
CREATE FUNCTION public.claim_auth_cleanup() RETURNS SETOF public.auth_cleanup_tasks LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE task public.auth_cleanup_tasks; available integer;
BEGIN
 PERFORM pg_advisory_xact_lock(76102622134919::bigint);
 SELECT greatest(0,5-count(*)) INTO available FROM public.auth_cleanup_tasks WHERE status='running' AND lease_until>clock_timestamp();
 FOR task IN SELECT * FROM public.auth_cleanup_tasks WHERE (status='pending' AND next_attempt<=clock_timestamp()) OR (status='running' AND lease_until<=clock_timestamp())
 ORDER BY created_at,id LIMIT available FOR UPDATE SKIP LOCKED LOOP
  UPDATE public.auth_cleanup_tasks SET status='running',fence=gen_random_uuid(),attempts=attempts+1,lease_until=clock_timestamp()+interval '60 seconds',updated_at=clock_timestamp()
  WHERE id=task.id RETURNING * INTO task;
  IF to_regclass('auth.sessions') IS NOT NULL THEN EXECUTE 'DELETE FROM auth.sessions WHERE user_id=$1' USING task.user_id; END IF;
  RETURN NEXT task;
 END LOOP;
END $$;
CREATE FUNCTION public.finish_auth_cleanup(p_id uuid,p_fence uuid,p_error text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
 UPDATE public.auth_cleanup_tasks SET status=CASE WHEN p_error IS NULL THEN 'completed' WHEN attempts>=8 THEN 'failed' ELSE 'pending' END,
 error=left(p_error,2000),next_attempt=clock_timestamp()+make_interval(secs=>least(3600,30*power(2,least(attempts,7))::int)),lease_until=NULL,updated_at=clock_timestamp()
 WHERE id=p_id AND fence=p_fence AND status='running' AND lease_until>clock_timestamp();
END $$;

CREATE FUNCTION public.retry_auth_cleanup(p_request uuid,p_actor uuid) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.admins WHERE id=p_actor) THEN RAISE EXCEPTION 'Superadmin required'; END IF;
 UPDATE public.auth_cleanup_tasks SET status='pending',attempts=0,next_attempt=clock_timestamp(),updated_at=clock_timestamp() WHERE request_id=p_request AND status='failed';
END $$;
CREATE FUNCTION public.review_worker_health() RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT EXISTS(SELECT 1 FROM public.review_worker_state WHERE last_seen>clock_timestamp()-interval '60 seconds');
$$;

-- Preserve legacy recovery for jobs that were not admitted through the durable queue.
CREATE OR REPLACE FUNCTION public.recover_expired_timetable_workers() RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE affected integer;
BEGIN
 UPDATE public.system_logs l SET status='failed',error_message='Legacy worker lease expired',completed_at=clock_timestamp(),updated_at=clock_timestamp()
 WHERE log_type='timetable_job' AND status IN('queued','running') AND updated_at<=clock_timestamp()-(coalesce((metadata->>'lease_seconds')::int,600)*interval '1 second')
 AND NOT EXISTS(SELECT 1 FROM public.review_jobs q WHERE q.id=l.id AND q.status IN('queued','running'));
 GET DIAGNOSTICS affected=ROW_COUNT; RETURN affected;
END $$;

DO $$ DECLARE f record; BEGIN
 FOR f IN SELECT oid::regprocedure name FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN
 ('guard_review_worker_completion','enqueue_review_job','claim_review_job','renew_review_job','finish_review_job','cancel_review_job','review_delete_accounts','claim_auth_cleanup','finish_auth_cleanup','retry_auth_cleanup','review_worker_health','recover_expired_timetable_workers') LOOP
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',f.name);
 EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',f.name);
 END LOOP;
END $$;
NOTIFY pgrst,'reload schema';



-- Source: review_scheduling.sql
-- Owner-run after review_operations.sql. Retains the global write lock.

SET LOCAL lock_timeout='10s';
CREATE TABLE public.cohort_schedule_outcomes (
 campus_id uuid NOT NULL REFERENCES public.campuses(id) ON DELETE CASCADE,
 academic_year text NOT NULL, semester integer NOT NULL CHECK(semester BETWEEN 1 AND 10), term_version integer NOT NULL,
 outcome text NOT NULL CHECK(outcome='not_required'), finalized_by uuid NOT NULL, finalized_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(campus_id,academic_year,semester,term_version)
);
ALTER TABLE public.cohort_schedule_outcomes ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.cohort_schedule_outcomes FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.cohort_schedule_outcomes TO service_role;

CREATE FUNCTION public.finalize_research_cohort(p_campus uuid,p_year text,p_semester integer,p_actor uuid,p_term integer,p_job uuid,p_fence uuid)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE course_ids uuid[];
BEGIN
 PERFORM pg_advisory_xact_lock(76102622134917::bigint);
 IF NOT EXISTS(SELECT 1 FROM public.faculty WHERE id=p_actor AND campus_id=p_campus AND role='campus_director')
 OR NOT EXISTS(SELECT 1 FROM public.campus_settings WHERE campus_id=p_campus AND term_version=p_term AND academic_year=p_year AND deadline<=now())
 THEN RAISE EXCEPTION 'Current director and closed registration required' USING ERRCODE='P4030'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.current_system_logs WHERE log_type='allocation_run' AND campus_id=p_campus AND academic_year=p_year AND semester=p_semester AND status='completed')
 THEN RAISE EXCEPTION 'Completed allocation required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.current_system_logs WHERE id=p_job AND log_type='timetable_job' AND campus_id=p_campus
  AND academic_year=p_year AND semester=p_semester AND status='running' AND metadata->>'fencing_token'=p_fence::text
  AND updated_at>now()-(coalesce((metadata->>'lease_seconds')::int,600)*interval '1 second')) THEN RAISE EXCEPTION 'Stale worker'; END IF;
 SELECT array_agg(DISTINCT cid) INTO course_ids FROM public.current_student_registrations r
 CROSS JOIN LATERAL unnest(ARRAY[r.slot_1_course_id,r.slot_2_course_id,r.slot_3_course_id,r.slot_4_course_id,
  r.slot_5_course_id,r.slot_6_course_id,r.slot_7_course_id,r.slot_8_course_id]) cid
 WHERE r.campus_id=p_campus AND r.academic_year=p_year AND r.semester=p_semester AND cid IS NOT NULL;
 IF coalesce(cardinality(course_ids),0)=0 OR EXISTS(SELECT 1 FROM unnest(course_ids) AS selected(course_id) LEFT JOIN public.courses c ON c.id=selected.course_id
 WHERE c.id IS NULL OR c.theory_hours_per_week IS NULL OR c.practical_hours_per_week IS NULL
 OR c.theory_hours_per_week<>0 OR c.practical_hours_per_week<>0) THEN RAISE EXCEPTION 'Cohort contains classroom components or has no allocated courses'; END IF;
 IF EXISTS(SELECT 1 FROM public.current_timetable_entries WHERE campus_id=p_campus AND academic_year=p_year AND semester=p_semester)
 THEN RAISE EXCEPTION 'Cohort already contains timetable entries'; END IF;
 INSERT INTO public.cohort_schedule_outcomes VALUES(p_campus,p_year,p_semester,p_term,'not_required',p_actor,now());
 UPDATE public.system_logs SET status='completed',progress=100,completed_at=now(),updated_at=now(),
 metadata=metadata||jsonb_build_object('schedulingStatus','not_required','classroomTimetableRequired',false)
 WHERE id=p_job AND metadata->>'fencing_token'=p_fence::text;
 INSERT INTO public.system_logs(log_type,event_type,user_id,user_role,campus_id,academic_year,semester,action,status,metadata)
 VALUES('audit_event','research_schedule_finalized',p_actor,'campus_director',p_campus,p_year,p_semester,'finalized zero-contact cohort','success',jsonb_build_object('jobId',p_job));
 RETURN true;
END $$;

CREATE FUNCTION public.guard_research_finalization() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE row_data jsonb; cid uuid; yr text; sem integer; term integer;
BEGIN
 row_data:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
 cid:=(row_data->>'campus_id')::uuid; yr:=row_data->>'academic_year'; sem:=(row_data->>'semester')::int; term:=(row_data->>'term_version')::int;
 IF EXISTS(SELECT 1 FROM public.cohort_schedule_outcomes o JOIN public.campus_settings s ON s.campus_id=o.campus_id AND s.term_version=o.term_version
 WHERE o.campus_id=cid AND o.academic_year=yr AND o.semester=sem AND (term IS NULL OR term=o.term_version)) THEN
  IF TG_TABLE_NAME='system_logs' AND row_data->>'log_type' NOT IN('allocation_run','timetable_job') THEN RETURN coalesce(NEW,OLD); END IF;
  RAISE EXCEPTION 'Research-only cohort scheduling is finalized' USING ERRCODE='P4090';
 END IF;
 RETURN coalesce(NEW,OLD);
END $$;
CREATE TRIGGER review_research_registration BEFORE INSERT OR UPDATE ON public.student_registrations FOR EACH ROW EXECUTE FUNCTION public.guard_research_finalization();
CREATE TRIGGER review_research_preferences BEFORE INSERT OR UPDATE ON public.registration_preferences FOR EACH ROW EXECUTE FUNCTION public.guard_research_finalization();
CREATE TRIGGER review_research_schedule BEFORE INSERT OR UPDATE ON public.timetable_entries FOR EACH ROW EXECUTE FUNCTION public.guard_research_finalization();
-- Prevent another allocation/generation claim after finalization without blocking the completion update itself.
CREATE TRIGGER review_research_job BEFORE INSERT ON public.system_logs FOR EACH ROW EXECUTE FUNCTION public.guard_research_finalization();

CREATE FUNCTION public.guard_research_contact_hours() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
 IF (NEW.theory_hours_per_week,NEW.practical_hours_per_week) IS DISTINCT FROM (OLD.theory_hours_per_week,OLD.practical_hours_per_week)
 AND EXISTS(SELECT 1 FROM public.cohort_schedule_outcomes o JOIN public.campus_settings s ON s.campus_id=o.campus_id AND s.term_version=o.term_version
  JOIN public.current_student_registrations r ON r.campus_id=o.campus_id AND r.academic_year=o.academic_year AND r.semester=o.semester
  WHERE NEW.id=ANY(ARRAY[r.slot_1_course_id,r.slot_2_course_id,r.slot_3_course_id,r.slot_4_course_id,r.slot_5_course_id,r.slot_6_course_id,r.slot_7_course_id,r.slot_8_course_id]))
 THEN RAISE EXCEPTION 'Contact hours of a finalized research-only cohort cannot change' USING ERRCODE='P4090'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER review_research_course BEFORE UPDATE ON public.courses FOR EACH ROW EXECUTE FUNCTION public.guard_research_contact_hours();

CREATE TABLE public.schedule_dependency_revisions (key text PRIMARY KEY, revision bigint NOT NULL DEFAULT 1);
ALTER TABLE public.schedule_dependency_revisions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.schedule_dependency_revisions FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE ON public.schedule_dependency_revisions TO service_role;
CREATE FUNCTION public.bump_schedule_dependency() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE oldrow jsonb; newrow jsonb; r jsonb; keys text[]:=ARRAY[]::text[]; k text;
BEGIN
 IF TG_OP<>'INSERT' THEN oldrow:=to_jsonb(OLD); END IF;
 IF TG_OP<>'DELETE' THEN newrow:=to_jsonb(NEW); END IF;
 IF TG_TABLE_NAME='departments' AND TG_OP='UPDATE' AND (oldrow-ARRAY['name','updated_at'])=(newrow-ARRAY['name','updated_at']) THEN RETURN NEW; END IF;
 IF TG_TABLE_NAME='faculty' AND TG_OP='UPDATE' AND
  (oldrow-ARRAY['full_name','email','updated_at'])=(newrow-ARRAY['full_name','email','updated_at']) THEN RETURN NEW; END IF;
 IF TG_TABLE_NAME='students' AND TG_OP='UPDATE' AND
  oldrow->'campus_id'=newrow->'campus_id' AND oldrow->'department_id'=newrow->'department_id' AND oldrow->'current_semester'=newrow->'current_semester' THEN RETURN NEW; END IF;
 IF TG_TABLE_NAME='courses' AND TG_OP='UPDATE' AND
  (oldrow-ARRAY['title','prerequisites','updated_at'])=(newrow-ARRAY['title','prerequisites','updated_at']) THEN RETURN NEW; END IF;
 IF TG_TABLE_NAME='campus_settings' AND TG_OP='UPDATE' AND
  oldrow->'academic_year'=newrow->'academic_year' AND oldrow->'deadline' IS NOT DISTINCT FROM newrow->'deadline'
  AND oldrow->'term_version'=newrow->'term_version' THEN RETURN NEW; END IF;
 FOREACH r IN ARRAY ARRAY[oldrow,newrow] LOOP
  IF r IS NULL THEN CONTINUE; END IF;
  IF TG_TABLE_NAME IN('student_registrations','teacher_course_assignments','timetable_entries','system_logs') THEN
   IF TG_TABLE_NAME='system_logs' AND r->>'log_type' NOT IN('timetable_job','allocation_run') THEN CONTINUE; END IF;
   keys:=array_append(keys,'cohort:'||(r->>'campus_id')||':'||(r->>'academic_year')||':'||(r->>'semester')||':'||(r->>'term_version'));
  END IF;
  IF TG_TABLE_NAME IN('teacher_course_assignments','timetable_entries') THEN keys:=array_append(keys,'teacher:'||(r->>'teacher_id')); END IF;
  IF TG_TABLE_NAME='courses' THEN keys:=array_append(keys,'course:'||(r->>'id')); END IF;
  IF TG_TABLE_NAME='faculty' THEN keys:=array_append(keys,'teacher:'||(r->>'id')); END IF;
  IF TG_TABLE_NAME='students' THEN keys:=array_append(keys,'student:'||(r->>'id')); END IF;
  IF TG_TABLE_NAME='departments' THEN keys:=array_append(keys,'department:'||(r->>'id')); END IF;
  IF TG_TABLE_NAME='campus_settings' THEN keys:=array_append(keys,'settings:'||(r->>'campus_id')); END IF;
  IF TG_TABLE_NAME='time_slots' THEN keys:=array_append(keys,'slots'); END IF;
  IF TG_TABLE_NAME='semester_blueprints' THEN keys:=array_append(keys,'blueprint:'||(r->>'department_id')||':'||(r->>'semester')); END IF;
 END LOOP;
 FOR k IN SELECT DISTINCT x FROM unnest(keys) x WHERE x IS NOT NULL ORDER BY x LOOP
  INSERT INTO public.schedule_dependency_revisions VALUES(k,1) ON CONFLICT(key) DO UPDATE SET revision=schedule_dependency_revisions.revision+1;
 END LOOP;
 RETURN coalesce(NEW,OLD);
END $$;
DO $$ DECLARE tab text; BEGIN
 FOREACH tab IN ARRAY ARRAY['student_registrations','teacher_course_assignments','timetable_entries','system_logs','courses','faculty','students','departments','campus_settings','time_slots','semester_blueprints'] LOOP
 EXECUTE format('CREATE TRIGGER review_revision AFTER INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.bump_schedule_dependency()',tab);
 END LOOP;
END $$;
CREATE FUNCTION public.manual_dependency_vector(p_campus uuid,p_year text,p_semester integer,p_term integer) RETURNS jsonb
LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog,public,pg_temp AS $$
 WITH regs AS (SELECT * FROM public.current_student_registrations WHERE campus_id=p_campus AND academic_year=p_year AND semester=p_semester),
 ids AS (SELECT DISTINCT unnest(ARRAY[slot_1_course_id,slot_2_course_id,slot_3_course_id,slot_4_course_id,slot_5_course_id,slot_6_course_id,slot_7_course_id,slot_8_course_id]) id FROM regs),
 teachers AS (SELECT DISTINCT teacher_id id FROM public.current_teacher_course_assignments WHERE campus_id=p_campus AND academic_year=p_year AND semester=p_semester),
 depts AS (SELECT department_id id FROM public.students WHERE id IN(SELECT student_id FROM regs) UNION SELECT department_id FROM public.courses WHERE id IN(SELECT id FROM ids)),
 keys AS (SELECT 'cohort:'||p_campus||':'||p_year||':'||p_semester||':'||p_term key UNION SELECT 'settings:'||p_campus UNION SELECT 'slots'
 UNION SELECT 'course:'||id FROM ids WHERE id IS NOT NULL UNION SELECT 'teacher:'||id FROM teachers WHERE id IS NOT NULL
 UNION SELECT 'student:'||student_id FROM regs UNION SELECT 'department:'||id FROM depts WHERE id IS NOT NULL
 UNION SELECT 'blueprint:'||id||':'||p_semester FROM depts WHERE id IS NOT NULL)
 SELECT coalesce(jsonb_object_agg(k.key,coalesce(r.revision,0) ORDER BY k.key),'{}'::jsonb) FROM keys k LEFT JOIN public.schedule_dependency_revisions r USING(key);
$$;

CREATE OR REPLACE FUNCTION public.timetable_manual_context(p_campus_id uuid,p_academic_year text,p_semester integer,
  p_actor_id uuid,p_expected_term integer) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER
SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE job public.system_logs; version integer; deadline timestamptz; year text; published boolean; revision text; entries jsonb;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM public.faculty WHERE id=p_actor_id AND role='campus_director' AND campus_id=p_campus_id) THEN
    RAISE EXCEPTION 'Campus director affiliation required' USING ERRCODE='P4030'; END IF;
  SELECT s.term_version,s.deadline,s.academic_year INTO version,deadline,year FROM public.campus_settings s WHERE campus_id=p_campus_id;
  IF version IS NULL OR p_expected_term IS DISTINCT FROM version OR p_academic_year IS DISTINCT FROM year THEN
    RAISE EXCEPTION 'Campus term changed; reload the portal' USING ERRCODE='P4090'; END IF;
  IF p_semester IS NULL OR p_semester NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION 'Invalid semester'; END IF;
  SELECT * INTO job FROM public.current_system_logs WHERE log_type='timetable_job' AND campus_id=p_campus_id
    AND academic_year=p_academic_year AND semester=p_semester ORDER BY created_at DESC,id DESC LIMIT 1;
  IF job.id IS NULL THEN RAISE EXCEPTION 'Run timetable generation before using the manual fallback'; END IF;
  IF job.status IN ('queued','running') OR EXISTS(SELECT 1 FROM public.current_system_logs WHERE campus_id=p_campus_id
    AND academic_year=p_academic_year AND semester=p_semester AND log_type IN ('allocation_run','timetable_job') AND status IN ('queued','running')) THEN
    RAISE EXCEPTION 'Wait for active allocation and timetable jobs to finish' USING ERRCODE='P4090'; END IF;
  IF job.status<>'failed' AND NOT(job.metadata ? 'reviewDraft') AND NOT(job.metadata ? 'manualDraft') THEN
    RAISE EXCEPTION 'Manual fallback is available after failed or incomplete generation'; END IF;
  SELECT EXISTS(SELECT 1 FROM public.current_timetable_entries e LEFT JOIN public.departments d ON d.id=e.department_id
    WHERE coalesce(e.campus_id,d.campus_id)=p_campus_id AND e.academic_year=p_academic_year AND e.semester=p_semester
    AND e.status='published') INTO published;
  IF NOT published AND (deadline IS NULL OR deadline>clock_timestamp()) THEN
    RAISE EXCEPTION 'Close student registrations before manual scheduling'; END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(e)||jsonb_build_object('time_slots',to_jsonb(t)) ORDER BY e.id),'[]'::jsonb)
    INTO entries FROM public.current_timetable_entries e JOIN public.time_slots t ON t.id=e.time_slot_id
    WHERE e.campus_id=p_campus_id AND e.academic_year=p_academic_year AND e.semester=p_semester;
  SELECT md5(jsonb_build_object('job',to_jsonb(job),'dependencies',
    public.manual_dependency_vector(p_campus_id,p_academic_year,p_semester,p_expected_term))::text) INTO revision;
  RETURN jsonb_build_object('job',to_jsonb(job),'entries',entries,'published',published,'revision',revision);
END $$;


DO $$ DECLARE f record; BEGIN
 FOR f IN SELECT oid::regprocedure name FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN
 ('guard_research_contact_hours','finalize_research_cohort','guard_research_finalization','bump_schedule_dependency','manual_dependency_vector','timetable_manual_context') LOOP
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',f.name);
 EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',f.name);
 END LOOP;
END $$;
NOTIFY pgrst,'reload schema';



-- Source: review_workflow_fixes.sql
-- Owner-run for databases with the November review release. Fresh releases include this file.

SET LOCAL lock_timeout='10s';
SELECT pg_advisory_xact_lock(76102622134917::bigint);
-- Resolve every original signature before replacing it, including on a standalone upgrade.
SELECT 'public.finish_review_job(uuid,uuid,text)'::regprocedure,
       'public.cancel_review_job(uuid,uuid)'::regprocedure,
       'public.review_delete_accounts(text,uuid,uuid)'::regprocedure;

CREATE OR REPLACE FUNCTION public.finish_review_job(p_id uuid,p_fence uuid,p_error text DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE complete boolean;
BEGIN
 PERFORM pg_advisory_xact_lock(76102622134917::bigint);
 SELECT status='completed' INTO complete FROM public.system_logs WHERE id=p_id;
 UPDATE public.review_jobs SET status=CASE WHEN complete THEN 'completed' ELSE 'failed' END,
 error=CASE WHEN complete THEN NULL ELSE left(p_error,2000) END,lease_until=NULL,updated_at=clock_timestamp() WHERE id=p_id AND fence=p_fence AND status='running' AND lease_until>clock_timestamp();
 IF NOT FOUND THEN RETURN false; END IF;
 IF NOT coalesce(complete,false) THEN UPDATE public.system_logs SET status='failed',completed_at=clock_timestamp(),updated_at=clock_timestamp(),
 error_message=coalesce(left(p_error,2000),error_message,'Worker did not complete') WHERE id=p_id AND metadata->>'fencing_token'=p_fence::text; END IF;
 RETURN true;
END $$;

CREATE OR REPLACE FUNCTION public.cancel_review_job(p_id uuid,p_actor uuid) RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
 PERFORM pg_advisory_xact_lock(76102622134917::bigint);
 IF NOT EXISTS(SELECT 1 FROM public.review_jobs q JOIN public.faculty f ON f.campus_id=q.campus_id
   WHERE q.id=p_id AND f.id=p_actor AND f.role='campus_director') THEN
   RAISE EXCEPTION 'Job unavailable in your campus' USING ERRCODE='P4030';
 END IF;
 -- A terminal domain write wins even if its worker has not acknowledged it yet.
 UPDATE public.system_logs SET status='failed',error_message='Cancelled by director',completed_at=clock_timestamp(),updated_at=clock_timestamp(),
 metadata=metadata||jsonb_build_object('fencing_token',gen_random_uuid()) WHERE id=p_id AND status IN('queued','running');
 IF NOT FOUND THEN RAISE EXCEPTION 'Job has already finished. Refresh its status.' USING ERRCODE='P4090'; END IF;
 UPDATE public.review_jobs SET status='cancelled',fence=gen_random_uuid(),lease_until=NULL,updated_at=clock_timestamp()
 WHERE id=p_id AND status IN('queued','running');
 IF NOT FOUND THEN RAISE EXCEPTION 'Job is no longer active. Refresh its status.' USING ERRCODE='P4090'; END IF;
 RETURN true;
END $$;

CREATE OR REPLACE FUNCTION public.review_delete_accounts(p_scope text,p_id uuid,p_actor uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE request uuid:=gen_random_uuid(); users uuid[]; depts uuid[]; course_ids uuid[]; student_ids uuid[]; result jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock(76102622134917::bigint);
 IF NOT EXISTS(SELECT 1 FROM public.admins WHERE id=p_actor) THEN RAISE EXCEPTION 'Superadmin required' USING ERRCODE='P4030'; END IF;
 IF p_scope='campus' THEN
  SELECT array_agg(id) INTO users FROM (SELECT id FROM public.students WHERE campus_id=p_id UNION SELECT id FROM public.faculty WHERE campus_id=p_id) u;
 ELSIF p_scope='department' THEN
  SELECT array_agg(id) INTO users FROM (SELECT id FROM public.students WHERE department_id=p_id UNION SELECT id FROM public.faculty WHERE department_id=p_id) u;
 ELSIF p_scope='faculty' THEN
  IF NOT EXISTS(SELECT 1 FROM public.faculty WHERE id=p_id AND role<>'teacher') THEN RAISE EXCEPTION 'Teachers remain HOD-managed'; END IF;
  users:=ARRAY[p_id];
 ELSE RAISE EXCEPTION 'Invalid cleanup scope'; END IF;
 INSERT INTO public.auth_cleanup_tasks(request_id,user_id,actor_id,scope,resource_id) SELECT request,id,p_actor,p_scope,p_id FROM unnest(users) id;
 IF p_scope IN('campus','department') THEN
  SELECT coalesce(array_agg(id),ARRAY[]::uuid[]) INTO depts FROM public.departments WHERE CASE WHEN p_scope='campus' THEN campus_id=p_id ELSE id=p_id END;
  SELECT coalesce(array_agg(id),ARRAY[]::uuid[]) INTO course_ids FROM public.courses WHERE department_id=ANY(depts);
  SELECT coalesce(array_agg(id),ARRAY[]::uuid[]) INTO student_ids FROM public.students WHERE id=ANY(users);
  IF EXISTS(SELECT 1 FROM public.review_jobs WHERE status IN('queued','running') AND (campus_id=p_id OR actor_id=ANY(users))) THEN
    RAISE EXCEPTION 'Cancel active campus work before deletion'; END IF;
  IF EXISTS(SELECT 1 FROM public.student_registrations r WHERE NOT r.student_id=ANY(student_ids)
    AND ARRAY[r.slot_1_course_id,r.slot_2_course_id,r.slot_3_course_id,r.slot_4_course_id,r.slot_5_course_id,r.slot_6_course_id,r.slot_7_course_id,r.slot_8_course_id] && course_ids)
   OR EXISTS(SELECT 1 FROM public.timetable_entries WHERE (course_id=ANY(course_ids) OR teacher_id=ANY(users))
     AND CASE WHEN p_scope='campus' THEN campus_id IS DISTINCT FROM p_id ELSE NOT department_id=ANY(depts) END)
   OR EXISTS(SELECT 1 FROM public.teacher_course_assignments WHERE (course_id=ANY(course_ids) OR teacher_id=ANY(users))
     AND (campus_id IS DISTINCT FROM CASE WHEN p_scope='campus' THEN p_id ELSE (SELECT campus_id FROM public.departments WHERE id=p_id) END
          OR (p_scope='department' AND NOT (course_id=ANY(course_ids)))))
  THEN RAISE EXCEPTION 'Shared courses or visiting teachers are still required outside the deletion scope'; END IF;
  DELETE FROM public.timetable_entries WHERE department_id=ANY(depts) OR (p_scope='campus' AND campus_id=p_id);
  DELETE FROM public.teacher_course_assignments WHERE course_id=ANY(course_ids) OR teacher_id=ANY(users) OR (p_scope='campus' AND campus_id=p_id);
  DELETE FROM public.students WHERE id=ANY(student_ids);
  DELETE FROM public.timetable_conflicts WHERE course_id=ANY(course_ids) OR blocking_course_id=ANY(course_ids);
  DELETE FROM public.semester_blueprints WHERE department_id=ANY(depts);
  DELETE FROM public.courses WHERE id=ANY(course_ids);
  DELETE FROM public.faculty WHERE id=ANY(users);
  DELETE FROM public.departments WHERE id=ANY(depts);
  IF p_scope='campus' THEN
   DELETE FROM public.campus_settings WHERE campus_id=p_id;
   DELETE FROM public.campuses WHERE id=p_id;
  END IF;
 ELSE DELETE FROM public.faculty WHERE id=p_id; END IF;
 INSERT INTO public.system_logs(log_type,event_type,user_id,user_role,action,resource_type,resource_id,status,metadata)
 VALUES('audit_event','accounts_deleted',p_actor,'superadmin','deleted domain records; Auth cleanup queued',p_scope,p_id,'success',
 jsonb_build_object('request_id',request,'auth_accounts',coalesce(cardinality(users),0)));
 RETURN jsonb_build_object('success',true,'cleanupRequestId',request,'cleanupStatus',CASE WHEN cardinality(users)>0 THEN 'pending' ELSE 'completed' END,
 'pendingAuthAccounts',coalesce(cardinality(users),0));
END $$;




